import React, { useState } from "react";
import { useNavigate, Link } from "react-router-dom";
import axios from "axios";
import "./Register.css";

function Register() {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    nom: "",
    email: "",
    password: "",
    confirmPassword: "",
    role: "student",
    matiere: "",
    specialite: "",
    classe: "",
    niveau: ""
  });
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState("");

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
    setError("");
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");

    // Validation
    if (formData.password !== formData.confirmPassword) {
      setError("Les mots de passe ne correspondent pas");
      return;
    }

    if (formData.password.length < 6) {
      setError("Le mot de passe doit contenir au moins 6 caractères");
      return;
    }

    setIsLoading(true);

    try {
      console.log('📝 Envoi des données d\'inscription...');
      
      // Préparer les données pour l'API
      const registerData = {
        nom: formData.nom,
        email: formData.email,
        password: formData.password,
        role: formData.role,
        matiere: formData.matiere,
        specialite: formData.specialite,
        classe: formData.classe,
        niveau: formData.niveau
      };

      const response = await axios.post('http://localhost:5000/api/auth/register', registerData);

      console.log('✅ Réponse inscription:', response.data);

      if (response.data.success) {
        alert("✅ Compte créé avec succès! Vous pouvez maintenant vous connecter.");
        navigate("/login");
      } else {
        setError(response.data.message || 'Erreur lors de l\'inscription');
      }

    } catch (err) {
      console.error('💥 Erreur d\'inscription:', err);
      
      const errorMessage = err.response?.data?.message || 
                          'Erreur lors de la création du compte';
      
      setError(errorMessage);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="register-container">
      <div className="register-card">
        <div className="register-header">
          <div className="logo">
            <i className="fas fa-graduation-cap"></i>
            <span>Gestion Cours</span>
          </div>
          <h2>Créer un compte</h2>
          <p>Rejoignez notre plateforme</p>
        </div>

        {error && (
          <div className="error-message">
            <i className="fas fa-exclamation-circle"></i>
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="register-form">
          <div className="form-group">
            <label htmlFor="nom">Nom complet *</label>
            <input
              type="text"
              id="nom"
              name="nom"
              value={formData.nom}
              onChange={handleChange}
              required
              placeholder="Votre nom complet"
              disabled={isLoading}
            />
          </div>

          <div className="form-group">
            <label htmlFor="email">Email *</label>
            <input
              type="email"
              id="email"
              name="email"
              value={formData.email}
              onChange={handleChange}
              required
              placeholder="exemple@email.com"
              disabled={isLoading}
            />
          </div>

          <div className="form-group">
            <label htmlFor="role">Je suis *</label>
            <select
              id="role"
              name="role"
              value={formData.role}
              onChange={handleChange}
              required
              disabled={isLoading}
            >
              <option value="student">Étudiant</option>
              <option value="prof">Professeur</option>
            </select>
          </div>

          {/* Champs conditionnels pour professeur */}
          {formData.role === 'prof' && (
            <>
              <div className="form-group">
                <label htmlFor="matiere">Matière enseignée</label>
                <input
                  type="text"
                  id="matiere"
                  name="matiere"
                  value={formData.matiere}
                  onChange={handleChange}
                  placeholder="Ex: Mathématiques, Informatique..."
                  disabled={isLoading}
                />
              </div>

              <div className="form-group">
                <label htmlFor="specialite">Spécialité</label>
                <input
                  type="text"
                  id="specialite"
                  name="specialite"
                  value={formData.specialite}
                  onChange={handleChange}
                  placeholder="Ex: Développement Web, IA..."
                  disabled={isLoading}
                />
              </div>
            </>
          )}

          {/* Champs conditionnels pour étudiant */}
          {formData.role === 'student' && (
            <>
              <div className="form-group">
                <label htmlFor="classe">Classe</label>
                <input
                  type="text"
                  id="classe"
                  name="classe"
                  value={formData.classe}
                  onChange={handleChange}
                  placeholder="Ex: Licence Informatique"
                  disabled={isLoading}
                />
              </div>

              <div className="form-group">
                <label htmlFor="niveau">Niveau</label>
                <input
                  type="text"
                  id="niveau"
                  name="niveau"
                  value={formData.niveau}
                  onChange={handleChange}
                  placeholder="Ex: L2, M1..."
                  disabled={isLoading}
                />
              </div>
            </>
          )}

          <div className="form-group">
            <label htmlFor="password">Mot de passe *</label>
            <input
              type="password"
              id="password"
              name="password"
              value={formData.password}
              onChange={handleChange}
              required
              placeholder="Minimum 6 caractères"
              minLength="6"
              disabled={isLoading}
            />
          </div>

          <div className="form-group">
            <label htmlFor="confirmPassword">Confirmer le mot de passe *</label>
            <input
              type="password"
              id="confirmPassword"
              name="confirmPassword"
              value={formData.confirmPassword}
              onChange={handleChange}
              required
              placeholder="Confirmez votre mot de passe"
              disabled={isLoading}
            />
          </div>

          <button 
            type="submit" 
            className={`btn btn-primary btn-full ${isLoading ? 'loading' : ''}`}
            disabled={isLoading}
          >
            {isLoading ? (
              <>
                <span className="spinner"></span>
                Création du compte...
              </>
            ) : (
              'Créer mon compte'
            )}
          </button>
        </form>

        <div className="register-footer">
          <p>
            Déjà un compte ? <Link to="/login">Se connecter</Link>
          </p>
        </div>
      </div>
    </div>
  );
}

export default Register;
